/* From Uiverse.io by 0xnihilism  - Tags: button, button hover effect , brutalism, minimalism, openai */
.__UIV_SCOPE__ .button-container {
  display: flex;
  justify-content: center;
  gap: 20px;
}

/* Common styles for both buttons */
.__UIV_SCOPE__ .brutalist-button {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 142px;
  height: 142px;
  color: #e5dede;
  font-weight: bold;
  text-decoration: none;
  position: relative;
  cursor: pointer;
  overflow: hidden;
  transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
}

/* Styles for the first button */
.__UIV_SCOPE__ .button-1 {
  background-color: #063525;
  border: 3px solid #42c498;
  border-radius: 12px;
  box-shadow: 4px 4px 1px #000000;
}

.__UIV_SCOPE__ .button-1:hover {
  background-color: #1a5c46;
  border-color: #030504;
  transform: translate(-6px, -6px) rotate(1deg);
  box-shadow: 10px 10px 0 #000000, 15px 15px 20px rgba(64, 164, 122, 0.2);
}

.__UIV_SCOPE__ .button-1::before,
.__UIV_SCOPE__ .button-1::after {
  content: "";
  position: absolute;
  top: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(
    90deg,
    transparent,
    rgba(255, 255, 255, 0.1),
    transparent
  );
  transition: 0.6s;
}

.__UIV_SCOPE__ .button-1::before {
  left: -100%;
}
.__UIV_SCOPE__ .button-1::after {
  left: 100%;
}

.__UIV_SCOPE__ .button-1:hover::before {
  animation: swipeRight 1.5s infinite;
}
.__UIV_SCOPE__ .button-1:hover::after {
  animation: swipeLeft 1.5s infinite;
}

@keyframes swipeRight {
  100% {
    transform: translateX(200%) skew(-45deg);
  }
}

@keyframes swipeLeft {
  100% {
    transform: translateX(-200%) skew(-45deg);
  }
}

/* Hover effects */
.__UIV_SCOPE__ .brutalist-button:hover .openai-logo {
  transform: translateY(-10px);
}

.__UIV_SCOPE__ .brutalist-button:hover .openai-icon {
  width: 40px;
  height: 40px;
}

.__UIV_SCOPE__ .bruta.brutalist-button:hover .openai-text {
  opacity: 1;
  max-height: 60px;
  margin-top: 8px;
}

/* Styles for the OpenAI logo and text */
.__UIV_SCOPE__ .openai-logo {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
  z-index: 3;
}

.__UIV_SCOPE__ .openai-icon {
  width: 64px;
  height: 64px;
  transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
}

.__UIV_SCOPE__ .openai-text {
  font-size: 24px;
  letter-spacing: 0.5px;
  transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
  opacity: 0;
  max-height: 0;
  overflow: hidden;
}

.__UIV_SCOPE__ .button-text {
  display: flex;
  flex-direction: column;
  align-items: center;
  line-height: 1.2;
  text-align: center;
  opacity: 0;
  max-height: 0;
  overflow: hidden;
  transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
  z-index: 3;
}

.__UIV_SCOPE__ .button-text span:first-child {
  font-size: 12px;
  font-weight: normal;
}

.__UIV_SCOPE__ .button-text span:last-child {
  font-size: 16px;
}

/* Hover effects */
.__UIV_SCOPE__ .brutalist-button:hover .openai-logo {
  transform: translateY(-10px);
}

.__UIV_SCOPE__ .brutalist-button:hover .openai-icon {
  width: 40px;
  height: 40px;
}

.__UIV_SCOPE__ .brutalist-button:hover .button-text,
.__UIV_SCOPE__ .brutalist-button:hover .openai-text {
  opacity: 1;
  max-height: 60px;
  margin-top: 8px;
}

/* Animation for the OpenAI logo */
@keyframes spin-and-zoom {
  0% {
    transform: rotate(0deg) scale(1);
  }
  50% {
    transform: rotate(180deg) scale(1.1);
  }
  100% {
    transform: rotate(360deg) scale(1);
  }
}

.__UIV_SCOPE__ .brutalist-button:hover .openai-icon {
  animation: spin-and-zoom 4s cubic-bezier(0.25, 0.8, 0.25, 1) infinite;
}

.__UIV_SCOPE__ .brutalist-button:hover .openai-text {
  text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.3);
}

.__UIV_SCOPE__ .brutalist-button:active .openai-icon,
.__UIV_SCOPE__ .brutalist-button:active .openai-text,
.__UIV_SCOPE__ .brutalist-button:active .button-text {
  transform: scale(0.95);
}
